1→//! Binary-discovered threetched methods owned by one sealed plugin contract.
//!
//! The binary supplies command words, flags and token schemas. This plugin owns
//! admission policy; help text cannot establish that a command is read-only.
//! opblob is the sole sealer. Filesystem and transport consumers project its
//! sealed declarations and dispatch through the existing MutationEngine gate.

use std::fs::File;
use std::io::Read;
10→use std::path::Path;
use std::process::Command;
use std::sync::{Arc, OnceLock, atomic::{AtomicBool, Ordering}};

use anyhow::{Context, Result, bail, ensure};
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::method_receipt::UnsupportedBeforeEffect;
use op_state_store::{CapabilityDecl, MethodDecl, PluginSchema, SideEffect};
use schemars::JsonSchema;
20→use serde::{Deserialize, Serialize};
use serde_json::Value;
use sha2::{Digest, Sha256};
use simd_json::OwnedValue;
use tched_fs::threetched_surface::{SurfaceSnapshot, ThreetchedSurface};

pub const PLUGIN_NAME: &str = "threetched";
const VERSION: &str = "1.0.0";
const MANIFEST_FORMAT: &str = "opdbus.threetched.v1";

30→/// Immutable discovery evidence, never a copy of the running configuration.
/// Capture selectors are build/seal inputs; these paths select the installed
/// runtime and stay identical when the candidate is staged into a release.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct ThreetchedState {
    pub binary: String,
    pub manifest: String,
    pub config_dir: String,
    pub binary_sha256: String,
40→    pub manifest_sha256: String,
    pub surface: Value,
}

struct Captured {
    state: ThreetchedState,
    surface: ThreetchedSurface,
    version: String,
}

50→static CAPTURED: OnceLock<std::result::Result<Captured, String>> = OnceLock::new();

/// Explicit authoring entry point for opblob and generated bridge contracts.
/// Each opblob command is a new process: every seal captures fresh bytes, shared
/// by all consumers in that invocation. Runtime never initializes this cache.
pub fn prepare_schema_capture() -> Result<()> {
    CAPTURED.get_or_init(|| capture().map_err(|error| format!("{error:#}")))
        .as_ref().map(|_| ()).map_err(|error| anyhow::anyhow!("{error}"))
}

60→pub(crate) fn is_schema_capture() -> bool {
    CAPTURED.get().is_some()
}

fn captured() -> Result<&'static Captured> {
    CAPTURED
        .get().context("threetched capture requires explicit schema preparation; runtime uses sealed blobs")?
        .as_ref()
        .map_err(|error| anyhow::anyhow!("{error}"))
}
70→
pub(crate) fn sealed_schema(plugin_id: &str) -> Result<PluginSchema> {
    let directory = std::env::var_os("OP_BLOB_CATALOG_DIR")
        .map(std::path::PathBuf::from)
        .unwrap_or_else(|| op_blob::catalog::DEFAULT_SHM_DIR.into());
    op_blob::catalog::read_plugin_state_store_schema(&directory, plugin_id)
        .with_context(|| format!("missing or invalid sealed {plugin_id} schema in {}", directory.display()))
}

pub(crate) fn sealed_state(plugin_id: &str) -> Result<OwnedValue> {
80→    sealed_schema(plugin_id)?.example
        .with_context(|| format!("sealed {plugin_id} schema has no discovery descriptor"))
}

pub(crate) fn capture_state() -> Result<&'static ThreetchedState> {
    Ok(&captured()?.state)
}

fn path_text(path: &Path) -> Result<String> {
    Ok(path.to_str().context("threetched path is not UTF-8")?.to_owned())
90→}

fn sha256_file(path: &Path) -> Result<String> {
    let mut file = File::open(path).with_context(|| format!("open {}", path.display()))?;
    let mut hasher = Sha256::new();
    let mut buffer = [0u8; 64 * 1024];
    loop {
        let count = file.read(&mut buffer)?;
        if count == 0 {
            break;
100→        }
        hasher.update(&buffer[..count]);
    }
    Ok(format!("{:x}", hasher.finalize()))
}

fn manifest_version(manifest: &Value, binary_hash: &str) -> Result<String> {
    ensure!(manifest["format"] == MANIFEST_FORMAT, "unsupported threetched manifest format");
    ensure!(manifest.pointer("/artifact/name").and_then(Value::as_str) == Some("threetched"), "manifest is not for the threetched executable");
    ensure!(manifest.pointer("/artifact/sha256").and_then(Value::as_str) == Some(binary_hash), "threetched executable differs from its manifest");
110→    let tag = manifest.pointer("/upstream/tag").and_then(Value::as_str)
        .context("threetched manifest has no upstream version")?;
    let version = tag.strip_prefix('v').filter(|value| !value.is_empty())
        .context("threetched manifest version must start with v")?;
    Ok(format!("threetched {version}"))
}

fn capture() -> Result<Captured> {
let env_path = |name: &str, fallback: &str| -> Result<std::path::PathBuf> {
    let path = std::env::var_os(name)
120→        .map(std::path::PathBuf::from)
        .unwrap_or_else(|| std::path::PathBuf::from(fallback));
    ensure!(path.is_absolute(), "{name} must be an absolute path");
    Ok(path)
};
let binary = env_path("THREETCHED_BIN", "/usr/local/libexec/op-dbus/threetched/threetched")?;
let manifest = env_path("THREETCHED_MANIFEST", "/usr/share/op-dbus/threetched-manifests/tched-router.json")?;
let config_dir = env_path("TCHED_ROUTER_CONFIG_DIR", "/var/lib/tched-router")?;
let (capture_binary, capture_manifest) = (
    std::env::var_os("THREETCHED_CAPTURE_BIN")
130→        .map(std::path::PathBuf::from)
        .unwrap_or_else(|| binary.clone()),
    std::env::var_os("THREETCHED_CAPTURE_MANIFEST")
        .map(std::path::PathBuf::from)
        .unwrap_or_else(|| manifest.clone()),
);
    let manifest_sha256 = sha256_file(&capture_manifest)?;
    let descriptor: Value = serde_json::from_reader(File::open(&capture_manifest)?)?;
    let binary_sha256 = sha256_file(&capture_binary)?;
    let version = manifest_version(&descriptor, &binary_sha256)?;
140→    let bare_version = version.strip_prefix("threetched ")
        .expect("manifest_version prefixes the bare version").to_owned();
    let surface = ThreetchedSurface::capture_with_config(&capture_binary, &config_dir)?;
    ensure!(surface.binary_sha256() == binary_sha256, "threetched executable changed during capture");
    ensure!(surface.version() == Some(version.as_str()), "threetched version differs from its manifest");
    ensure!(sha256_file(&capture_manifest)? == manifest_sha256, "threetched manifest changed during capture");
    let state = ThreetchedState {
        binary: path_text(&binary)?,
        manifest: path_text(&manifest)?,
        config_dir: path_text(&config_dir)?,
150→        binary_sha256: surface.binary_sha256().to_owned(),
        manifest_sha256,
        surface: serde_json::to_value(surface.snapshot())?,
    };
    Ok(Captured { state, surface, version: bare_version })
}

/// The pinned binary surface captured once at seal.
pub(crate) fn surface() -> Result<&'static ThreetchedSurface> {
    Ok(&captured()?.surface)
160→}

/// The threetched `config schema` document from the same pinned capture.
pub(crate) fn config_schema() -> Result<&'static Value> {
    Ok(captured()?.surface.schema_json())
}

/// The bare upstream version (e.g. "0.8.4") verified against the manifest.
pub(crate) fn binary_version() -> Result<&'static str> {
    Ok(captured()?.version.as_str())
170→}

fn command_policy(method: &str) -> (String, String) {
    // Exact method bytes keep dotted/hyphenated CLI names distinct. This is a
    // policy identifier, not an inferred CLI type or a hardcoded method table.
    let key = format!("c{:x}", Sha256::digest(method.as_bytes()));
    (
        format!("cap.software.threetched.call.{key}@v1"),
        format!("mut.software.threetched.call.{key}@v1"),
    )
180→}

fn schema_from_capture(captured: &Captured) -> Result<PluginSchema> {
    let root = serde_json::to_value(schemars::schema_for!(ThreetchedState))?;
    let mut schema = super::schemars_adapter::plugin_schema_from_json(
        PLUGIN_NAME, VERSION, "Commands discovered from the pinned threetched binary", &root,
    );
    schema.category = "software".into();
    schema.display_name = Some("threetched".into());
    schema.tags = vec!["threetched".into(), "binary".into(), "immutable".into()];
190→    schema.immutable_paths = root["properties"].as_object().context("missing threetched descriptor fields")?
        .keys().map(|name| format!("/{name}")).collect();
    // Publish closed metadata fields; opaque discovery evidence is sealed in example.
