bash -c 'set -a; source "$HOME/.bash_secrets"; set +a
python3 - << "PY"
import json, os, urllib.request
state = {
  "task": "Decide whether a tched mention in op-grpc-bridge is the removed hand-rolled schema bridge, or a label for the gRPC envelope / a real ZeroClaw 0.8.4 command. The spelling tched is not itself a defect.",
  "pinned_binary": "threetched filename, native identity zeroclaw 0.8.4. Schema is captured from that binary and sealed as plugin id threetched.",
  "zeroclaw_0_8_4_commands": ["quickstart","onboard","agent","gateway","acp","daemon","service","doctor","status","security","estop","cron","models","providers","channel","agents","channels","integrations","skills","browse","sop","migrate","auth","hardware","peripheral","memory","config","update","self-test","eval","completions","desktop","plugin","locales","help"],
  "excerpt": {
    "file": "crates/op-grpc-bridge/src/grpc/tched_router.proto",
    "lines_1_to_21": """// threetched gRPC schema host contract.\n// This proto only defines the service envelope. The actual PluginSchema payload\n// is serialized JSON from `tched_router_schema()` in `op-plugins` — never hand-edited\n// structs here.\nsyntax = \"proto3\";\npackage tched_router;\n\nservice TchedRouterService {\n  rpc GetSchema(GetSchemaRequest) returns (SchemaResponse);\n  rpc WatchSchema(WatchSchemaRequest) returns (stream SchemaEvent);\n}\n// schema_json comment: Canonical PluginSchema JSON serialized by `tched_router_schema()`."""
  },
  "server_behavior": "server.rs GetSchema returns loader.get() JSON. DEFAULT_SCHEMA_PLUGIN_ID is threetched. The host comment says the schema is read from the sealed blob catalog, not generated in the bridge."
}
body = {
  "model": "jev-latest",
  "state": state,
  "questions": {
    "cites_named_schema_function": {
      "type": "noul",
      "instructions": "Does the proto comment claim the schema JSON is produced by a function named tched_router_schema in op-plugins?",
      "criteria": {
        "true": "The comment names tched_router_schema as the serializer of the PluginSchema JSON.",
        "false": "The comment does not name a schema-producing function."
      }
    },
    "what_tched_router_names": {
      "type": "choice",
      "instructions": "In this proto excerpt, what do the package tched_router and service TchedRouterService name?",
      "criteria": {
        "removed_hand_rolled_schema": "They name the old hand-written schema producer that was removed.",
        "grpc_envelope": "They name the gRPC envelope that carries schema JSON supplied by the loader.",
        "zeroclaw_command": "They name one of the ZeroClaw 0.8.4 CLI commands in state.",
        "insufficient": "The excerpt does not show which of those it is."
      }
    },
    "spelling_is_the_defect": {
      "type": "noul",
      "instructions": "Is the presence of the letters tched in these identifiers itself a defect?",
      "criteria": {
        "true": "The spelling alone is the defect, regardless of what the code does.",
        "false": "The spelling can label a still-valid envelope or a ZeroClaw path."
      }
    }
  }
}
req = urllib.request.Request(
  "https://api.typesafe.ai/v1/systemone",
  data=json.dumps(body).encode(),
  headers={"Authorization": "Bearer " + os.environ["TYPESAFE_API_KEY"], "Content-Type": "application/json"},
)
with urllib.request.urlopen(req, timeout=60) as resp:
  print(resp.read().decode())
PY'

