    /// A publish on `opdbus/ack/<owner-key>`: parse the ack receipt, verify
    /// it against the committed private turn, and stop the broker chain with
    /// that verdict. An unverifiable ack is recorded as a flagged broker
    /// event (the hallucination signal) and denied at the broker, so an
    /// untracked tool call never acquires its ack topic.
    async fn on_tool_use_ack(
        &self,
140→        owner_key_hex: &str,
        message: &exhook::Message,
    ) -> Response<ValuedResponse> {
        let ack = match crate::wake_doorbell::parse_tool_use_ack(&message.payload) {
            Ok(ack) => ack,
            Err(reason) => {
                tracing::warn!(reason, "tool-use ack refused: unparsable receipt");
                let _ = self
                    .record_event(
                        "on_tool_use_ack",
150→                        &message.from,
                        Some(&message.topic),
                        Some("flag:unparsable-receipt"),
                    )
                    .await;
                return stop_with(false);
            }
        };
        if ack.owner_key != owner_key_hex {
            tracing::warn!(
160→                ack_owner = %ack.owner_key,
                topic_owner = %owner_key_hex,
                "tool-use ack refused: receipt owner does not match its topic"
            );
            let _ = self
                .record_event(
                    "on_tool_use_ack",
                    &message.from,
                    Some(&message.topic),
                    Some("flag:owner-mismatch"),
170→                )
                .await;
            return stop_with(false);
        }
        match crate::wake_doorbell::verify_tool_use_ack(&self.mutation_engine, &ack).await {
            Ok(true) => {
                debug!(turn_id = %ack.turn_id, "tool-use ack verified");
                stop_with(true)
            }
            Ok(false) => {
180→                tracing::warn!(turn_id = %ack.turn_id, "tool-use ack refused: no committed turn matches this receipt");
                let _ = self
                    .record_event(
                        "on_tool_use_ack",
                        &message.from,
                        Some(&message.topic),
                        Some("flag:hallucinated-receipt"),
                    )
                    .await;
                stop_with(false)
190→            }
            Err(error) => {
                tracing::error!(%error, "tool-use ack verification failed");
                record_event_quiet(
                    &self.mutation_engine,
                    "on_tool_use_ack",
                    &message.from,
                    Some(&message.topic),
                    Some("flag:verify-unavailable"),
                )
200→                .await;
                // Fail closed: never let an unverified receipt through.
                stop_with(false)
            }
        }
    }
}

