/// Topic carrying a response tool-use ack. `<owner-key>` is the
/// chat_response projection owner key (`sha256(principal_id)`), the same
/// identity the committed signal announces.

/// Verifies a published tool-use ack against the durable committed turn:
/// the turn must exist in some principal's private scope with exactly this
/// turn_id and turn_hash. Content-free: the probe never reads turn_json.
/// `false` is the hallucination signal.
pub(crate) async fn verify_tool_use_ack(
    engine: &MutationEngine,
    ack: &ToolUseAck,
) -> anyhow::Result<bool> {
    let store = engine.chat_response_cozo().await?;
    let (turn_id, turn_hash) = (ack.turn_id.clone(), ack.turn_hash.clone());
    tokio::task::spawn_blocking(move || store.chat_turn_receipt_exists(&turn_id, &turn_hash))
        .await
        .map_err(|error| anyhow::anyhow!("tool-use ack verify worker failed: {error}"))?
        .map_err(|error| anyhow::anyhow!("tool-use ack probe failed: {error}"))
}

rawInput.new_string:
/// Verifies a published tool-use ack against the execution tracker.
/// `turn_id` is the execution id and `turn_hash` is `exec_hash`.
/// `false` is the hallucination signal: missing, mismatched, or a record
/// whose stored hash does not recompute.
pub(crate) async fn verify_tool_use_ack(
    tracker: &op_execution_tracker::ExecutionTracker,
    ack: &ToolUseAck,
) -> bool {
    let Some(record) = tracker.get_execution(&ack.turn_id).await else {
        return false;
    };
    record.hash() == ack.turn_hash && record.verify_integrity()
}

