/// One subscription: every completed execution is appended to its identity
/// sled session ledger. That ledger is the vectorization input. Events
/// without a session, or for a session that has no sled, are not written.
pub(crate) fn subscribe_execution_tracker(
    engine: Arc<MutationEngine>,
    tracker: Arc<op_execution_tracker::ExecutionTracker>,
) {
    let mut events = tracker.subscribe();
    let lookup = Arc::clone(&tracker);
    tokio::spawn(async move {
        loop {
            let event = match events.recv().await {
                Ok(event) => event,
                Err(tokio::sync::broadcast::error::RecvError::Lagged(skipped)) => {
                    tracing::warn!(skipped, "identity sled execution subscription lagged");
                    continue;
                }
                Err(tokio::sync::broadcast::error::RecvError::Closed) => break,
            };
            let op_execution_tracker::ExecutionEvent::Completed(id, _) = event else {
                continue;
            };
            if let Err(error) = write_execution_on_sled(&engine, &lookup, &id).await {
                tracing::debug!(%error, execution_id = %id, "execution stayed off the identity sled");
            }
        }
    });
}

async fn write_execution_on_sled(
    engine: &MutationEngine,
    tracker: &op_execution_tracker::ExecutionTracker,
    id: &str,
) -> anyhow::Result<()> {
    let Some(record) = tracker.get_execution(id).await else {
        return Ok(());
    };
    let Some(session_id) = record
        .metadata
        .get("session_id")
        .filter(|session| !session.is_empty())
        .cloned()
    else {
        return Ok(());
    };
    let store = engine.identity_sled_store()?;
    if load_revision(store, &session_id).await?.record.is_none() {
        return Ok(());
    }
    let content = serde_json::json!({
        "execution_id": record.id,
        "tool": record.tool_name,
        "exec_hash": record.exec_hash,
        "success": record.success,
        "summary": record.output_summary,
    })
    .to_string();
    let kind = "execution".to_string();
    let subid = "mut.service.identity-sled.session.event.record@v1".to_string();
    let operation_id = format!("execution-sled:{}", record.id);
    let cozo = store.cozo.clone();
    let callback_session = session_id;
    let publication = engine
        .commit_identity_intent(operation_id, move |_| {
            let seq = cozo.append_session_event(
                &callback_session,
                &kind,
                &subid,
                &content,
                now(),
            )?;
            let snapshot = cozo.read_identity_recovery_state(MAX_EVENTS_IN_STATE)?;
            Ok((
                Some(state_value(&snapshot)?),
                DurableResult {
                    value: u64::try_from(seq)?,
                    replayed: false,
                },
            ))
        })
        .await?;
    publication_value(publication)?;
    Ok(())
}

