/// Keep one delegated execution and publish it to subscribers.
/// The ring drops the oldest record when full.
pub async fn remember(&self, record: ExecutionRecord) {
    let id = record.id.clone();
    let success = record.success;
    {
        let mut records = self.records.write().await;
        records.push(record);
        if records.len() > self.max_history {
            records.remove(0);
        }
    }
    let _ = self
        .event_sender
        .send(ExecutionEvent::Completed(id, success));
}

