/// Best-effort bounded event record that never fails the publish path.
async fn record_event_quiet(
    engine: &Arc<MutationEngine>,
    event_type: &str,
    client: &str,
    topic: Option<&str>,
    detail: Option<&str>,
) {
    let event_data = broker_event(event_type, client, topic, detail);
    let event_value = match simd_json::serde::to_owned_value(&event_data) {
        Ok(value) => value,
        Err(error) => {
            tracing::warn!(%error, event_type, "could not serialize broker event");
            return;
        }
    };
    let result = engine
        .process_authoritative_change(
            "emqx".into(),
            "/org/opdbus/v1/plugins/emqx".into(),
            ChangeType::Signal,
            Some(BROKER_EVENT_SIGNAL.into()),
            None,
            event_value,
            vec![BROKER_EVENT_SUBID.into()],
            "grpc:emqx.exhook.v3".into(),
            None,
            ChangeSource::Grpc,
        )
        .await;
    if let Err(error) = result {
        tracing::warn!(%error, event_type, "could not record broker event");
    }
}


