/// One subscription: every completed execution is appended to its identity
/// sled session ledger. That ledger is the vectorization input. Events
/// without a session, or for a session that has no sled, are not written.
pub(crate) fn subscribe_execution_tracker(
    engine: Arc<MutationEngine>,
    tracker: Arc<op_execution_tracker::ExecutionTracker>,
) {
1130→    let mut events = tracker.subscribe();
    let lookup = Arc::clone(&tracker);
    tokio::spawn(async move {
        loop {
            let event = match events.recv().await {
                Ok(event) => event,
                Err(tokio::sync::broadcast::error::RecvError::Lagged(skipped)) => {
                    tracing::warn!(skipped, "identity sled execution subscription lagged");
                    continue;
                }
1140→                Err(tokio::sync::broadcast::error::RecvError::Closed) => break,
            };
            let op_execution_tracker::ExecutionEvent::Completed(id, _) = event else {
                continue;
            };
            if let Err(error) = write_execution_on_sled(&engine, &lookup, &id).await {
                tracing::debug!(%error, execution_id = %id, "execution stayed off the identity sled");
            }
        }
    });
1150→}

async fn write_execution_on_sled(
    engine: &MutationEngine,
    tracker: &op_execution_tracker::ExecutionTracker,
    id: &str,
) -> anyhow::Result<()> {
    let Some(record) = tracker.get_execution(id).await else {
        return Ok(());
    };
