    /// not sealed (retired/unknown): then only the header is embedded.
    fn lines_for(&self, block: &ChainBlockRef) -> (Vec<(String, String)>, Option<String>) {
        let mut lines = Vec::new();
        let Some(schema) = self.schema(&block.category) else {
            return (lines, None);
80→        };

