/// Lines the original sealed schema allows into a vector. `None` drops the
/// execution from the subscription: unknown plugin, unknown method, or a
/// schema that cannot be read.
fn schema_filtered_execution(
    record: &op_execution_tracker::ExecutionRecord,
) -> Option<String> {
    let (plugin, method) = record.tool_name.split_once('.')?;
    let pinned = crate::sealed_schema_reader::read_manifest_pinned_schema_document(
        &crate::sealed_schema_reader::blob_catalog_dir_from_env(),
        plugin,
    )
    .ok()?;
    let method = pinned.schema.methods.get(method)?;
    let args_schema: serde_json::Value =
        simd_json::serde::from_owned_value(method.args.clone()).unwrap_or_default();
    let input: serde_json::Value =
        simd_json::serde::from_owned_value(record.input.clone()).unwrap_or_default();
    let mut lines = Vec::new();
    lines.push(format!("tool: {}", record.tool_name));
    lines.push(format!("subid: {}", method.subid));
    for field in op_state_store::schema_projection::described_fields(&args_schema, &input) {
        let mut value = field.value;
        if value.len() > 512 {
            let mut cut = 512;
            while !value.is_char_boundary(cut) {
                cut -= 1;
            }
            value.truncate(cut);
            value.push('…');
        }
        if field.description.is_empty() {
            lines.push(format!("{}: {value}", field.path));
        } else {
            lines.push(format!("{} ({}): {value}", field.path, field.description));
        }
    }
    Some(lines.join("\n"))
}

