/// The declared capability of `plugin.method` from the sealed catalog: an
/// action exercises exactly what the contract declares, never a caller pick.
fn declared_capability(plugin: &str, method: &str) -> Result<(Option<String>, String)> {
    let pinned = crate::sealed_schema_reader::read_manifest_pinned_schema_document(
        &crate::sealed_schema_reader::blob_catalog_dir_from_env(),
        plugin,
    )?;
    let declaration = pinned
        .schema
        .methods
        .get(method)
        .with_context(|| format!("{plugin}.{method} is not a sealed method"))?;
    Ok((declaration.required_capability.clone(), pinned.schema_hash))
}

fn truncate(text: &str, max: usize) -> String {
    if text.len() <= max {
        text.to_string()
    } else {
        let mut cut = max;
        while !text.is_char_boundary(cut) {
            cut -= 1;
        }
        format!("{}…", &text[..cut])
    }
}

fn delegated_execution(
    tool_name: &str,
    input: &serde_json::Value,
    output: &serde_json::Value,
    principal_id: &str,
    session_id: &str,
) -> op_execution_tracker::ExecutionRecord {
    let owned = |value: &serde_json::Value| {
        simd_json::serde::to_owned_value(value.clone()).unwrap_or_else(|_| {
            simd_json::serde::to_owned_value(serde_json::json!({}))
                .expect("empty object converts to owned json")
        })
    };
    op_execution_tracker::ExecutionRecord::builder(tool_name)
        .input(owned(input))
        .output(owned(output))
        .initiated_by(principal_id)
        .metadata("session_id", session_id)
        .build()
}

