impl HookProviderService {
    /// A publish on `opdbus/ack/<owner-key>`: parse the ack receipt and
    /// verify it against the execution tracker. An unverifiable ack is
    /// recorded as a flagged broker event and denied, so an untracked tool
    /// call never acquires its ack topic. `chat_response` is one tool the
    /// delegation path can record; it is not the receipt store.
    async fn on_tool_use_ack(
        &self,
        owner_key_hex: &str,
150→        message: &exhook::Message,
    ) -> Response<ValuedResponse> {
        let ack = match crate::wake_doorbell::parse_tool_use_ack(&message.payload) {
            Ok(ack) => ack,
            Err(reason) => {
                tracing::warn!(reason, "tool-use ack refused: unparsable receipt");
                let _ = self
                    .record_event(
                        "on_tool_use_ack",
                        &message.from,
160→                        Some(&message.topic),
                        Some("flag:unparsable-receipt"),
                    )
                    .await;
                return stop_with(false);
            }
        };
        if ack.owner_key != owner_key_hex {
            tracing::warn!(
                ack_owner = %ack.owner_key,
170→                topic_owner = %owner_key_hex,
                "tool-use ack refused: receipt owner does not match its topic"
            );
            let _ = self
                .record_event(
                    "on_tool_use_ack",
                    &message.from,
                    Some(&message.topic),
                    Some("flag:owner-mismatch"),
                )
180→                .await;
            return stop_with(false);
        }
        if crate::wake_doorbell::verify_tool_use_ack(&self.executions, &ack).await {
            debug!(turn_id = %ack.turn_id, "tool-use ack verified");
            stop_with(true)
        } else {
            tracing::warn!(turn_id = %ack.turn_id, "tool-use ack refused: no tracked execution matches this receipt");
            let _ = self
                .record_event(
190→                    "on_tool_use_ack",
                    &message.from,
                    Some(&message.topic),
                    Some("flag:hallucinated-receipt"),
                )
                .await;
            stop_with(false)
        }
    }
}
