    "builder_build": "pub fn build(self) -> ExecutionRecord {\n    let id = Uuid::new_v4().to_string();\n    let exec_hash = hash_execution(&self.tool_name, &self.input, &self.output, &self.prev_hash);\n    ExecutionRecord { id, exec_hash, success: true, /* other fields copied from the builder */ }\n}",
