    "ack_hook": "async fn on_tool_use_ack(...) {\n    let ack = match parse_tool_use_ack(&message.payload) { Ok(ack) => ack, Err(_) => { record flag:unparsable-receipt; return stop_with(false); } };\n    if ack.owner_key != owner_key_hex { record flag:owner-mismatch; return stop_with(false); }\n    if verify_tool_use_ack(&self.executions, &ack).await { stop_with(true) }\n    else { record flag:hallucinated-receipt; stop_with(false) }\n}\nThe file crates/op-grpc-bridge contains no call to chat_turn_receipt_exists.",
    "hook_new": "pub fn new(mutation_engine: Arc<MutationEngine>, executions: Arc<ExecutionTracker>) -> Self {\n    let queue = RunQueue::spawn(mutation_engine.clone(), DEFAULT_CAPACITY, DEFAULT_CONCURRENCY, executions.clone());\n    Self::with_queue(mutation_engine, queue, executions)\n}",
    "server_mount": "let executions = Arc::new(op_execution_tracker::ExecutionTracker::new(1000));\nidentity_sled_dispatch::subscribe_execution_tracker(mutation_engine.clone(), executions.clone());\nHookProviderService::new(mutation_engine.clone(), executions);",
    "remember_call": "if let Ok(output) = &result {\n    executions.remember(delegated_execution(&name, &action.args, output, &scope.principal_id, &scope.session_id)).await;\n}\nThis sits after dispatch_method_call_with_identity. A failed or refused result is not passed to remember.",
    "delegated_execution": "ExecutionRecord::builder(tool_name).input(owned(input)).output(owned(output)).initiated_by(principal_id).metadata(\"session_id\", session_id).build()",
    "subscribe": "let mut events = tracker.subscribe();\nloop {\n    let event = events.recv().await ...;\n    let ExecutionEvent::Completed(id, _) = event else { continue; };\n    write_execution_on_sled(&engine, &lookup, &id).await;\n}",
    "write_sled": "let Some(record) = tracker.get_execution(id).await else { return Ok(()); };\nlet Some(session_id) = record.metadata.get(\"session_id\").filter(|s| !s.is_empty()).cloned() else { return Ok(()); };\nif load_revision(store, &session_id).await?.record.is_none() { return Ok(()); }\nlet Some(content) = schema_filtered_execution(&record) else { return Ok(()); };\ncommit_identity_intent(..., append_session_event(session, \"execution\", subid, &content, now()));",
    "schema_filter": "fn schema_filtered_execution(record: &ExecutionRecord) -> Option<String> {\n    let (plugin, method) = record.tool_name.split_once('.')?;\n    let pinned = read_manifest_pinned_schema_document(..., plugin).ok()?;\n    let method = pinned.schema.methods.get(method)?;\n    let args_schema = from_owned_value(method.args.clone());\n    let input = from_owned_value(record.input.clone());\n    lines: tool name, method.subid, then described_fields(&args_schema, &input) as path and value.\n    record.output and output_summary are not added to the lines.\n    Some(lines.join(\"\\n\"))\n}",
