import os, re
root = "crates/op-grpc-bridge"
pat = re.compile(r"zeroclow|ZeroClaw|tched_router|TchedRouter")
kinds = {}
for dirpath, _, files in os.walk(root):
    for f in files:
        if not f.endswith((".rs", ".proto", ".toml")):
            continue
        path = os.path.join(dirpath, f)
        try:
            text = open(path, encoding="utf-8", errors="replace").read()
        except Exception:
            continue
        # count token classes
        for m in re.finditer(r"[A-Za-z0-9_]*?(?:zeroclow|ZeroClaw|tched_router|TchedRouter)[A-Za-z0-9_]*", text):
            tok = m.group(0)
            kinds.setdefault(tok, 0)
            kinds[tok] += 1
print(f"{len(kinds)} distinct tokens")
for tok, n in sorted(kinds.items(), key=lambda kv: -kv[1])[:80]:
    print(f"{n:5} {tok}")
PY

