import os,re
root="crates/op-grpc-bridge"
toks={}
for dp,_,fs in os.walk(root):
  for f in fs:
    if not f.endswith(('.rs','.proto','.toml')): continue
    p=os.path.join(dp,f)
    text=open(p,encoding='utf-8',errors='replace').read()
    for m in re.finditer(r'[A-Za-z0-9_]*tched_router[A-Za-z0-9_]*', text):
      toks[m.group(0)]=toks.get(m.group(0),0)+1
for t,n in sorted(toks.items(), key=lambda kv:-kv[1]):
  print(f"{n:4} {t}")
PY

