fn main() -> Result<(), Box<dyn std::error::Error>> {
10→    for name in [
        "ZEROCLOW_CAPTURE_BIN",
        "ZEROCLOW_CAPTURE_MANIFEST",
        "ZEROCLOW_BIN",
        "ZEROCLOW_MANIFEST",
        "ZEROCLOW_ROUTER_CONFIG_DIR",
    ] {
        println!("cargo:rerun-if-env-changed={name}");
    }
    for (capture, runtime, default) in [
20→        ("ZEROCLOW_CAPTURE_BIN", "ZEROCLOW_BIN", "/usr/local/libexec/op-dbus/zeroclow/zeroclow"),
        (
            "ZEROCLOW_CAPTURE_MANIFEST",
            "ZEROCLOW_MANIFEST",
            "/usr/share/op-dbus/zeroclow-manifests/zeroclow-router.json",
        ),
    ] {
        let selected = PathBuf::from(
            env::var_os(capture)
                .or_else(|| env::var_os(runtime))
30→                .unwrap_or_else(|| default.into()),
        );
        // Watch both the selected link and its resolved release artifact.
        println!("cargo:rerun-if-changed={}", selected.display());
        if let Ok(resolved) = std::fs::canonicalize(&selected)
            && resolved != selected
        {
            println!("cargo:rerun-if-changed={}", resolved.display());
        }
    }
40→    let out_dir = PathBuf::from(env::var("OUT_DIR").unwrap());

